import{_ as o,o as d,c,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const r=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/ONEWAY.md","filePath":"manual-zh/ONEWAY.md","lastUpdated":1785684581000}'),l={name:"manual-zh/ONEWAY.md"};function S(E,e,t,A,i,n){return d(),c("div",null,[...e[0]||(e[0]=[a(`<h3 id="_15-14-oneway" tabindex="-1">15.14 ONEWAY <a class="header-anchor" href="#_15-14-oneway" aria-label="Permalink to &quot;15.14 ONEWAY&quot;">​</a></h3><pre><code>ONEWAY
        [/VARIABLES = ] var_list BY var
        /MISSING={ANALYSIS,LISTWISE} {EXCLUDE,INCLUDE}
        /CONTRAST= value1 [, value2] ... [,valueN]
        /STATISTICS={DESCRIPTIVES,HOMOGENEITY}
        /POSTHOC={BONFERRONI, GH, LSD, SCHEFFE, SIDAK, TUKEY, ALPHA ([value])}
</code></pre><p><code>ONEWAY</code> 过程由一个自变量分组的变量进行单因素方差分析。它用于比较被划分为两个以上组的总体的均值。</p><p>要分析的因变量应在 <code>VARIABLES</code> 子命令中给出。变量列表之后必须跟上 <code>BY</code> 关键字以及自变量（或因子）变量的名称。</p><p>你可以使用 <code>STATISTICS</code> 子命令让 PSPP 显示辅助信息。接受的选项有：</p><ul><li>DESCRIPTIVES 显示按自变量分组的各组描述统计量。</li><li>HOMOGENEITY 显示变量及其各组的方差齐性 Levene 检验。</li></ul><p><code>CONTRAST</code> 子命令在你预期各组之间存在某些差异时使用。该子命令之后必须跟一个数字列表，这些数字是要检验的组的系数。系数数量必须与不同的组数（或自变量的值数）相对应。如果系数总和不等于零，PSPP 会显示警告，但仍继续分析。<code>CONTRAST</code> 子命令最多可给出 10 次，以指定不同的对照检验。<code>MISSING</code> 子命令定义如何处理缺失值。如果指定 <code>LISTWISE</code>，则自变量或任何因变量含有缺失值的个案都将被忽略。如果指定 <code>ANALYSIS</code>，则当自变量缺失或当前正在分析的因变量缺失时，该个案被忽略。默认值为 <code>ANALYSIS</code>。<code>EXCLUDE</code> 设置表示值属于用户缺失值的变量将被排除在分析之外。<code>INCLUDE</code> 设置表示将它们包含在内。默认值为 <code>EXCLUDE</code>。</p><p>使用 <code>POSTHOC</code> 子命令可以对数据进行多次成对比较。可用的比较方法有：</p><ul><li><code>LSD</code> 最小显著差异法。</li><li><code>TUKEY</code> Tukey 诚实显著性差异法。</li><li><code>BONFERRONI</code> Bonferroni 检验。</li><li><code>SCHEFFE</code> Scheffé 检验。</li><li><code>SIDAK</code> Sidak 检验。</li><li><code>GH</code> Games-Howell 检验。</li></ul><p>使用可选语法 <code>ALPHA(value)</code> 指示 <code>ONEWAY</code> 应以值所指定的置信水平执行事后检验。如果未指定 <code>ALPHA(value)</code>，则使用的置信水平为 0.05。</p>`,10)])])}const N=o(l,[["render",S]]);export{r as __pageData,N as default};
